const out={};
for (const c of ["KASE","KLXV","KJAC","KTEX"]) {
  page.goto("https://www.airnav.com/airport/"+c);
  out[c]=page.evaluate(()=>{const m=document.body.innerText.match(/Elevation:[^\n]*/);return m&&m[0]});
}
return out;
